/** Painted moon disc, generated by scripts/moon-texture */
export const MOON_TEXTURE_URL = `${import.meta.env.BASE_URL}textures/moon.webp`;

/**
 * Placement on the sky dome; angles in degrees, azimuth 0 straight ahead, positive to the right.
 * The moon moves a little as the camera tilts, so it stays in frame from the hero to Contact:
 * landscape, from the hero's upper right (clear of the title) to the centre, behind the dagger
 * area; portrait, from under the hero title to the lower half, below the start of the text.
 */
export const MOON_PLACEMENT = {
    distance: 75,
    landscape: { heroElevation: 28, tiltedElevation: 33, heroAzimuth: 30, tiltedAzimuth: 0 },
    portrait: { heroElevation: 16, tiltedElevation: 29, heroAzimuth: 0, tiltedAzimuth: 0 },
    /** Extra rise from Experience to Contact */
    driftRise: 2
} as const;

/** Disc diameter as a share of the viewport height; portrait screens also cap it by width */
export const MOON_SIZE = {
    heroHeightShare: 0.14,
    tiltedHeightShare: 0.38,
    maxWidthShare: 0.7
} as const;

/** Pale cool disc with a warm rim; both lean toward the active section's accent, at most by accentShare */
export const MOON_COLORS = {
    disc: '#dfe6f2',
    rim: '#f0ae78',
    halo: '#9fb6d8',
    accentShare: 0.25
} as const;

export const RIM_TEXTURE = {
    size: 512,
    /** Ring stroke width, as a share of the texture size */
    lineWidthShare: 0.005,
    /** Brightest on the lit (upper left) side, fading to this alpha on the far side */
    farSideAlpha: 0.08
} as const;

/** Sprite sizes relative to the disc diameter */
export const MOON_LAYERS = {
    /** The rim canvas draws its ring two line widths inside its edge: scaled so it sits on the disc edge */
    rimScale: 0.5 / (0.5 - 2 * RIM_TEXTURE.lineWidthShare),
    haloScale: 2,
    haloOpacity: 0.45
} as const;

export const HALO_TEXTURE = { size: 256 } as const;

/** Dark painted cloud bands drifting across the moon; tilted like wind-blown streaks */
export const STREAK_TEXTURE = {
    width: 1024,
    height: 256,
    seed: 41,
    strokeCount: 28,
    /** Darker than the night sky, so the streaks only ever darken what they cross */
    color: '#030409',
    /** Canvas blur, in pixels, for soft brushed edges */
    blur: 6
} as const;

/** Fixed alpha mask of every streak sprite: its ends and edges fade out instead of cutting off */
export const STREAK_MASK = {
    width: 256,
    height: 64,
    /** Share of the width (each side) and height (top and bottom) over which the mask fades */
    sideFade: 0.35,
    edgeFade: 0.3
} as const;

type MoonStreak = {
    /** Offset from the disc centre and size, in disc diameters */
    offsetY: number;
    width: number;
    height: number;
    /** Radians, applied to the sprite */
    rotation: number;
    /** Texture widths per second; off under reduced motion */
    driftSpeed: number;
    opacity: number;
};

/** Front to back; the low tier keeps only the first */
export const MOON_STREAKS: MoonStreak[] = [
    { offsetY: 0.08, width: 1.5, height: 0.3, rotation: -0.22, driftSpeed: 0.006, opacity: 0.7 },
    { offsetY: -0.22, width: 1.3, height: 0.2, rotation: -0.18, driftSpeed: 0.004, opacity: 0.5 },
    { offsetY: 0.3, width: 1.2, height: 0.16, rotation: -0.26, driftSpeed: 0.008, opacity: 0.4 }
];

/** Draw order among the transparent sky sprites */
export const MOON_RENDER_ORDER = { halo: 1, disc: 2, rim: 3, streaks: 4 } as const;
